class Solution {
public:
    long long countSubarrays(vector<int>& nums) {
        long long answer = 0, length = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            length = i > 0 && nums[i] > nums[i - 1] ? length + 1 : 1;
            answer += length;
        }
        return answer;
    }
};
